package hexadecimal

import (
	"errors"
	"fmt"
)

// ParseHex converts a hexadecimal string to a decimal int64.
// It returns an error containing "syntax" for invalid input and
// "range" for values that do not fit in an int64.
func ParseHex(in string) (int64, error) {
	if in == "" {
		return 0, errors.New("syntax error: empty string")
	}

	var value int64
	for _, c := range in {
		var digit int64
		switch {
		case c >= '0' && c <= '9':
			digit = int64(c - '0')
		case c >= 'a' && c <= 'f':
			digit = int64(c-'a') + 10
		case c >= 'A' && c <= 'F':
			digit = int64(c-'A') + 10
		default:
			return 0, fmt.Errorf("syntax error: invalid hex character %q", c)
		}

		// Overflow check: value*16 + digit must fit in int64.
		if value > (math.MaxInt64 - digit) / 16 {
			return 0, fmt.Errorf("range error: value %q out of range for int64", in)
		}
		value = value*16 + digit
	}
	return value, nil
}
