package hexadecimal

import (
	"errors"
	"fmt"
	"strings"
)

// maxInt64 is the largest value representable in an int64.
const maxInt64 = 9223372036854775807

// hexValue returns the decimal value of a single hex digit,
// or -1 if c is not a valid hex digit.
func hexValue(c byte) int64 {
	switch {
	case c >= '0' && c <= '9':
		return int64(c - '0')
	case c >= 'a' && c <= 'f':
		return int64(c-'a') + 10
	case c >= 'A' && c <= 'F':
		return int64(c-'A') + 10
	}
	return -1
}

// ParseHex converts a hexadecimal string (e.g. "10af8c") to its decimal
// equivalent, computed by hand without any parsing libraries.
//
// It returns an error whose message contains "syntax" for strings that are
// not valid hexadecimal, and "range" for values that do not fit in an int64.
func ParseHex(in string) (int64, error) {
	if in == "" {
		return 0, errors.New("syntax error: empty string")
	}

	var value int64
	for i := 0; i < len(in); i++ {
		digit := hexValue(in[i])
		if digit < 0 {
			return 0, fmt.Errorf("syntax error: %q is not a valid hexadecimal digit", in[i])
		}

		// Accumulate value*16 + digit, checking for overflow first.
		if value > (maxInt64-digit)/16 {
			return 0, fmt.Errorf("range error: %q does not fit in an int64", in)
		}
		value = value*16 + digit
	}
	return value, nil
}

// HandleErrors calls ParseHex on each input and returns a matching list of
// error cases: "none", "syntax", or "range".
func HandleErrors(inputs []string) []string {
	results := make([]string, len(inputs))
	for i, in := range inputs {
		_, err := ParseHex(in)
		switch {
		case err == nil:
			results[i] = "none"
		case strings.Contains(strings.ToLower(err.Error()), "syntax"):
			results[i] = "syntax"
		default:
			results[i] = "range"
		}
	}
	return results
}
